CREATE OR REPLACE FUNCTION railcommand_guard.assert_stored_object(p_bucket text, p_path text, p_type text, p_size bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_size is null or p_size<=0 or length(trim(coalesce(p_type,'')))=0 then
    raise exception 'Invalid attachment metadata' using errcode='22023';
  end if;
  if not exists(select 1 from storage.objects o where o.bucket_id=p_bucket and o.name=p_path) then
    raise exception 'Uploaded attachment is not available yet' using errcode='P0001';
  end if;
  if not exists(select 1 from storage.objects o where o.bucket_id=p_bucket and o.name=p_path
    and case when jsonb_typeof(o.metadata->'size')='number' and (o.metadata->>'size') ~ '^[0-9]+$'
      then (o.metadata->>'size')::numeric=p_size else false end
    and jsonb_typeof(o.metadata->'mimetype')='string'
    and lower(trim(o.metadata->>'mimetype'))=lower(trim(p_type))) then
    raise exception 'Uploaded attachment metadata does not match' using errcode='22023';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION railcommand_guard.can_write_object(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_project uuid:=railcommand_guard.project_from_path(p_name);
begin
  if p_bucket not in ('project-photos','thermal-photos','project-documents') then return true; end if;
  if not exists(select 1 from public.project_members pm where pm.project_id=v_project
    and pm.profile_id=(select auth.uid()) and pm.can_edit) then return false; end if;
  if split_part(p_name,'/',2)='daily_log' then
    return railcommand_guard.can_write_daily_log(v_project) and exists(select 1 from public.daily_logs dl
      where dl.id=split_part(p_name,'/',3)::uuid and dl.project_id=v_project);
  end if;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION railcommand_guard.check_daily_log_attachment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_parts text[];v_bucket text;
begin
  if tg_op='UPDATE' and (old.entity_type='daily_log' or new.entity_type='daily_log')
    and (old.id is distinct from new.id or old.project_id is distinct from new.project_id
      or old.entity_type is distinct from new.entity_type or old.entity_id is distinct from new.entity_id
      or old.uploaded_by is distinct from new.uploaded_by or old.idempotency_key is distinct from new.idempotency_key
      or old.file_url is distinct from new.file_url or old.file_size is distinct from new.file_size
      or lower(trim(old.file_type)) is distinct from lower(trim(new.file_type))
      or old.photo_category is distinct from new.photo_category) then
    raise exception 'Daily-log attachment identity and stored file cannot be reassigned' using errcode='22023';
  end if;
  if new.entity_type <> 'daily_log' then return new; end if;
  if not railcommand_guard.can_write_daily_log(new.project_id) then
    raise exception 'Permission denied' using errcode='42501';
  end if;
  v_bucket:=case new.photo_category when 'standard' then 'project-photos'
    when 'thermal' then 'thermal-photos' when 'document' then 'project-documents' else null end;
  -- getPublicUrl is the existing stored-path format, not permission to read it
  -- publicly. Authenticated download helpers derive a signed local Storage URL.
  v_parts:=regexp_match(new.file_url,'^(?:https://[a-z0-9-]+[.]supabase[.]co)?/storage/v1/object/public/(project-photos|thermal-photos|project-documents)/(.+)$');
  if v_bucket is null or v_parts is null or v_parts[1]<>v_bucket
    or railcommand_guard.project_from_path(v_parts[2]) is distinct from new.project_id
    or split_part(v_parts[2],'/',2)<>'daily_log' or split_part(v_parts[2],'/',3)<>new.entity_id::text then
    raise exception 'Invalid attachment storage destination' using errcode='22023';
  end if;
  perform railcommand_guard.assert_stored_object(v_bucket,v_parts[2],new.file_type,new.file_size);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION railcommand_guard.check_daily_log_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.id is distinct from new.id or old.project_id is distinct from new.project_id
    or old.created_by is distinct from new.created_by or old.idempotency_key is distinct from new.idempotency_key then
    raise exception 'Daily-log identity cannot be reassigned' using errcode='22023';
  end if;
  return new;
end;
$function$
